SELF_CLOSING = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}

class Node:
    def __init__(self, tag=None, attrs=None, parent=None, text=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        self.parent = parent
        self.text = text

    def is_text(self):
        return self.tag is None

class MyParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = Node(tag="root")
        self.stack = [self.root]
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attr_dict = {}
        for k,v in attrs:
            if v is None:
                v = ""
            attr_dict[k.lower()] = v
        node = Node(tag=tag, attrs=attr_dict, parent=self.stack[-1])
        self.stack[-1].children.append(node)
        if tag not in SELF_CLOSING:
            self.stack.append(node)
    def handle_endtag(self, tag):
        tag = tag.lower()
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                break
    def handle_data(self, data):
        if data == "":
            return
        node = Node(tag=None, text=data, parent=self.stack[-1])
        self.stack[-1].children.append(node)
    def handle_entityref(self, name):
        text = f"&{name};"
        node = Node(tag=None, text=text, parent=self.stack[-1])
        self.stack[-1].children.append(node)
    def handle_charref(self, name):
        text = f"&#{name};"
        node = Node(tag=None, text=text, parent=self.stack[-1])
        self.stack[-1].children.append(node)
    def handle_comment(self, data):
        pass
    def handle_decl(self, decl):
        pass

def parse_html(s):
    parser = MyParser()
    parser.feed(s)
    parser.close()
    return parser.root

