    dfs(root)

def get_body_root(root):
    def find_tag(node, tag):
        if node.tag == tag:
            return node
        for ch in node.children:
            if not ch.is_text():
                res = find_tag(ch, tag)
                if res:
                    return res
        return None
    body = find_tag(root, "body")
    if body:
        return body
    html_node = find_tag(root, "html")
    if html_node:
        return html_node
    return root

