def is_space(c):
    return c in " \t\n\r\f\v"

def is_punct(c):
    return c in r"""!"#$%&'()*+,-./:;<=>?@[\]^_`{|}~"""

def left_flanking(text, pos, run_len):
    after_idx = pos + run_len
    after = text[after_idx] if after_idx < len(text) else ""
    before = text[pos-1] if pos>0 else ""
    if after and is_space(after):
        return False
    if after and is_punct(after):
        if before and not is_space(before) and not is_punct(before):
            return False
    return True

def right_flanking(text, pos, run_len):
    before = text[pos-1] if pos>=1 else ""
    after_idx = pos+run_len
    after = text[after_idx] if after_idx < len(text) else ""
    if before and is_space(before):
        return False
    if before and is_punct(before):
        if after and not is_space(after) and not is_punct(after):
            return False
    return True

def escape_text_smart(text, is_block_start=False):
    # handle backslash, backtick, bracket, <, >, etc. and star/underscore runs
    # First handle block-start for ">", "#", list markers etc via pre-check but we will handle inside loop
    n = len(text)
