                    # escape dot/parens
                    res.append(text[i:j])
                    res.append("\\"+text[j])
                    i=j+1
                    continue
        if c == "\\":
            res.append("\\\\")
            i+=1
            continue
        if c == "`":
            res.append("\\`")
            i+=1
            continue
        if c == "[":
            # rule: escape if at start or preceded by space or "!"
            if i==0 or text[i-1] in " \t\n" or text[i-1]=="!":
                res.append("\\[")
            else:
                res.append("[")
            i+=1
            continue
        if c == "<":
            res.append("&lt;")
            i+=1
            continue
        if c == ">":
            res.append("&gt;")
            i+=1
            continue
        if c == "*" or c == "_":
            j=i
            while j < n and text[j]==c:
                j+=1
            run_len = j-i
            # need flanking
            is_left = left_flanking(text, i, run_len)
            is_right = right_flanking(text, i, run_len)
            esc_count=0
            if is_left:
                esc_count = run_len
            elif is_right:
