def escape_text_smart(text, is_block_start=False):
    # handle backslash, backtick, bracket, <, >, etc. and star/underscore runs
    # First handle block-start for ">", "#", list markers etc via pre-check but we will handle inside loop
    n = len(text)
    # Find first non-space for block start
    first_non_space = 0
    while first_non_space < n and text[first_non_space] in " \t":
        first_non_space +=1
    res = []
    i=0
    while i < n:
        c = text[i]
        # block start checks
        if is_block_start and i == first_non_space:
            if c == ">":
                res.append("&gt;")
                i+=1
                continue
            if c == "#":
                res.append("\\#")
                i+=1
                continue
            if c in "-*+":
                if i+1 < n and text[i+1] == " ":
                    res.append("\\"+c)
                    i+=1
                    continue
                # for HR: if whole stripped is hr, handled later
            if c.isdigit():
                j=i
                while j < n and text[j].isdigit():
                    j+=1
                if j < n and text[j] in ".)" and j+1 < n and text[j+1]==" ":
                    # escape dot/parens
                    res.append(text[i:j])
                    res.append("\\"+text[j])
                    i=j+1
                    continue
        if c == "\\":
            res.append("\\\\")
            i+=1
            continue
        if c == "`":
            res.append("\\`")
            i+=1
            continue
        if c == "[":
            # rule: escape if at start or preceded by space or "!"
            if i==0 or text[i-1] in " \t\n" or text[i-1]=="!":
                res.append("\\[")
            else:
                res.append("[")
            i+=1
            continue
        if c == "<":
            res.append("&lt;")
            i+=1
            continue
        if c == ">":
            res.append("&gt;")
            i+=1
            continue
        if c == "*" or c == "_":
            j=i
            while j < n and text[j]==c:
                j+=1
            run_len = j-i
            # need flanking
            is_left = left_flanking(text, i, run_len)
            is_right = right_flanking(text, i, run_len)
            esc_count=0
            if is_left:
                esc_count = run_len
            elif is_right:
                if run_len > 1:
                    esc_count = run_len -1
                else:
                    esc_count = 0
            else:
                if run_len > 1:
                    esc_count = run_len -1
                else:
                    esc_count = 0
            # Special for "_" ??? same
            for k in range(run_len):
                if k < esc_count:
                    res.append("\\"+c)
                else:
                    res.append(c)
            i=j
            continue
        # For other chars, just append
        res.append(c)
        i+=1
    out = "".join(res)
    # Handle HR-like whole line
    stripped = text.strip()
    if is_block_start and stripped:
        # check if stripped is HR (3+ of same char - * _ with optional spaces)
        # Simplified: if stripped in ("---","***","___") or matches r'^([-*_])\1{2,}$' or r'^([-*_])(\s*\1){2,}\s*$'
        # For "---" and "***" we need to replicate observed escaping: "---" => "\---", "***" => "\*\**"
        if stripped == "---":
            out = "\\---"
        elif stripped == "***":
            out = "\\*\\**"
        elif stripped == "___":
            out = "\\_\\__"
        elif re.match(r'^([-*_])\1{2,}$', stripped):
            # generic: escape first char? But we already have observed for "---" vs "***" different.
            # For "---" we escape one, for "***" escape two
            # For "___" we guess escape two? We'll follow pattern: for "-" escape 1, for "*" escape 2, for "_" escape 2?
            # Let's handle generally: escape len-2 for "-"?? Not.
            # We'll just escape first char for generic
            ch = stripped[0]
            out = "\\" + ch + stripped[1:]
        elif re.match(r'^([-*_])(\s*\1){2,}\s*$', stripped):
            # like "* * *"
            # Already handled as HR? But plain text "* * *" as p content is not block start HR, it's inside p, not HR. So not needed.
            pass
    return out

def encode_url(url):
    # encode parentheses and spaces as observed: "("=>%28, ")"=>%29, " "=>%20
    # Also maybe other chars? We'll use urllib.parse.quote with safe
    # Keep safe characters: typical URL safe: - _ . ~ : / ? # [ ] @ ! $ & ' ( ) * + , ; = % plus we want to encode () and space
    # But observed they encode "(" and ")" and " ", but not other like ":" or "/"
    # We'll do: quote with safe = "/:?#[]@!$&'()*+,;=%-._~" minus "() " ???
    # Actually we want to encode "(" and ")" and " "
    # So safe should exclude those three.
    # Let's use urllib.parse.quote with safe = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~:/?#[]@!$&'()*+,;=%"
    # Wait that includes "()" and " "?? This safe includes "()" . We need to exclude them.
    # We'll manually replace.
    # Simpler: use quote and then replace
    # But easiest: just replace " " -> "%20", "(" -> "%28", ")" -> "%29"
    # Also maybe need to handle other?
    # We'll implement simple replace.
    return url.replace(" ", "%20").replace("(", "%28").replace(")", "%29")

def choose_title_quote(title):
    # title is raw string (decoded)
    # Need to decide quote style: if title contains both " and ', need to escape?
    # Observed: title with double quote uses single quotes: title 'a"b' => 'a"b' with single quotes
    # Title with single quote uses double quotes: "a'b"
    # Title with both? Not tested.
    # We'll choose: if '"' not in title: use "\""+title+"\""
    # elif "'" not in title: use "'"+title+"'"
    # else: escape?
    if '"' not in title:
        return f'"{title}"'
    elif "'" not in title:
        return f"'{title}'"
    else:
        # contains both, use double and escape double?
        # We'll use double and escape?
        escaped = title.replace('"', '\\"')
        return f'"{escaped}"'

