    def extract_language(self, code_node, pre_node):
        # check code class
        for attr_node in [code_node, pre_node]:
            cls = attr_node.attrs.get("class","")
            for token in cls.split():
                if token.startswith("language-"):
                    return token[len("language-"):]
                if token.startswith("lang-"):
                    return token[len("lang-"):]
        return ""

    def get_raw_text(self, node):
        # collect all text recursively
        parts = []
        def dfs(n):
            if n.is_text():
                parts.append(n.text)
            else:
                for ch in n.children:
                    dfs(ch)
        dfs(node)
        return "".join(parts)

    def contains_br(self, node):
        # search for br tag inside
        found=False
        def dfs(n):
            nonlocal found
            if n.tag == "br":
                found=True
                return
            for ch in n.children:
                if not ch.is_text():
                    dfs(ch)
        dfs(node)
        return found

