            # For domain "https://example.com" and href "" => "https://example.com" (no trailing slash?)
            # Our earlier test: href "" with domain "https://example.com" gave "https://example.com" (no slash)
            # urljoin with empty gives base
            base = self.domain
            # Ensure base without trailing slash? urljoin handles
            return encode_url(urllib.parse.urljoin(base, href)) if href else encode_url(base)  # but base may already have path?
        # Check for scheme like "mailto:", "http:", "https:", "ftp:" etc, or "//"
        if re.match(r'^[a-zA-Z][a-zA-Z0-9+.\-]*:', href):
            return encode_url(href)
        if href.startswith("//"):
            # protocol-relative: use domain's scheme + href
            # e.g., href "//example.com/foo" with domain "https://example.com" => "https://example.com/foo"
            # urljoin will handle: "https://example.com" + "//example.com/foo" => "https://example.com/foo" ??? Actually urljoin with // will keep // host
            # Let's use urljoin
            joined = urllib.parse.urljoin(self.domain, href)
            return encode_url(joined)
        # For other relative, use urljoin
        joined = urllib.parse.urljoin(self.domain, href)
        return encode_url(joined)

